const ham = $input.first().json.output || '';
let sonuc;
try {
  const m = ham.match(/\{[\s\S]*\}/);
  sonuc = JSON.parse(m ? m[0] : ham);
} catch (e) {
  sonuc = { karar: 'RED', gerekce: 'Denetçi çıktısı okunamadı, güvenlik için reddedildi.', duzeltme: '' };
}
if (!['ONAY', 'RED'].includes(sonuc.karar)) sonuc.karar = 'RED';
return [{ json: { output: JSON.stringify(sonuc), karar: sonuc.karar } }];
